begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public', 'github_webhook_deliveries', 'delivery inbox exists');
select has_column('public', 'github_webhook_deliveries', 'delivery_id', 'delivery id stored');
select has_column('public', 'github_webhook_deliveries', 'body_sha256', 'body digest stored');
select has_column('public', 'github_webhook_deliveries', 'internal_event_id', 'stable event id stored');
select has_column('public', 'github_webhook_deliveries', 'version', 'optimistic version stored');
select has_function('public', 'register_github_webhook_delivery', array['uuid','text','text','text','bigint','bigint','text','text','boolean','timestamp with time zone'], 'register RPC exists');
select has_function('public', 'claim_github_webhook_dispatch', array['uuid','bigint','timestamp with time zone'], 'claim RPC exists');
select has_function('public', 'complete_github_webhook_dispatch', array['uuid','bigint','text','timestamp with time zone'], 'complete dispatch RPC exists');
select has_function('public', 'complete_github_webhook_installation', array['uuid','bigint','text','timestamp with time zone'], 'installation state RPC exists');
select ok((select relrowsecurity from pg_class where oid='public.github_webhook_deliveries'::regclass), 'RLS enabled');
select ok(not has_table_privilege('anon','public.github_webhook_deliveries','select,insert,update,delete') and not has_table_privilege('authenticated','public.github_webhook_deliveries','select,insert,update,delete') and not has_table_privilege('service_role','public.github_webhook_deliveries','select,insert,update,delete'), 'no direct table access');
select ok(has_function_privilege('service_role','public.register_github_webhook_delivery(uuid,text,text,text,bigint,bigint,text,text,boolean,timestamptz)','execute') and not has_function_privilege('authenticated','public.register_github_webhook_delivery(uuid,text,text,text,bigint,bigint,text,text,boolean,timestamptz)','execute'), 'service role only RPC');

insert into auth.users (id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('a7600000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','phase6@example.test','',now(),'{}','{}',now(),now());
insert into public.users(id) values ('a7600000-0000-4000-8000-000000000001');
insert into public.github_installations(id,user_id,installation_id,github_account_id,github_account_login,account_type,repository_selection,status,last_verified_at) values ('a7610000-0000-4000-8000-000000000001','a7600000-0000-4000-8000-000000000001',81001,71001,'phase6','User','selected','active',now());
insert into public.selected_repositories(id,user_id,github_installation_id,github_repository_id,owner_login,name,full_name,visibility,is_private,is_fork,is_archived,is_disabled,default_branch) values ('a7620000-0000-4000-8000-000000000001','a7600000-0000-4000-8000-000000000001','a7610000-0000-4000-8000-000000000001',91001,'owner','repo','owner/repo','private',true,false,false,false,'main');
insert into public.projects(id,user_id,selected_repository_id,core_goal,current_stage_goal,status) values ('a7630000-0000-4000-8000-000000000001','a7600000-0000-4000-8000-000000000001','a7620000-0000-4000-8000-000000000001','goal','stage','in_development');

create temporary table registration as select public.register_github_webhook_delivery('11111111-1111-4111-8111-111111111111','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','issues','opened',81001,91001,'owner/repo','github-webhook:11111111-1111-4111-8111-111111111111',true,'2026-08-06T04:00:00Z') value;
select is((select value->>'outcome' from registration),'new','first delivery is new');
select is((select value->>'project_id' from registration),'a7630000-0000-4000-8000-000000000001','trusted project mapped');
select is((select count(*)::text from public.github_webhook_deliveries where delivery_id='11111111-1111-4111-8111-111111111111'),'1','one delivery row');
select is(public.register_github_webhook_delivery('11111111-1111-4111-8111-111111111111','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','issues','opened',81001,91001,'owner/repo','github-webhook:11111111-1111-4111-8111-111111111111',true,'2026-08-06T04:00:01Z')->>'outcome','duplicate','exact replay duplicate');
select is(public.register_github_webhook_delivery('11111111-1111-4111-8111-111111111111','cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc','issues','opened',81001,91001,'owner/repo','github-webhook:11111111-1111-4111-8111-111111111111',true,'2026-08-06T04:00:01Z')->>'outcome','conflict','digest conflict rejected');
select is(public.claim_github_webhook_dispatch('11111111-1111-4111-8111-111111111111',1,'2026-08-06T04:00:00Z')->>'claimed','true','first lease claimed');
select is(public.claim_github_webhook_dispatch('11111111-1111-4111-8111-111111111111',2,'2026-08-06T04:00:01Z')->>'claimed','false','concurrent lease refused');
select is(public.claim_github_webhook_dispatch('11111111-1111-4111-8111-111111111111',2,'2026-08-06T04:01:01Z')->>'claimed','true','expired lease reclaimed');
select lives_ok($$select public.complete_github_webhook_dispatch('11111111-1111-4111-8111-111111111111',3,'provider-1','2026-08-06T04:01:02Z')$$,'dispatch completed');
select is((select status from public.github_webhook_deliveries where delivery_id='11111111-1111-4111-8111-111111111111'),'dispatched','terminal status persisted');
select is(public.register_github_webhook_delivery('33333333-3333-4333-8333-333333333333','dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd','installation','deleted',81001,null,null,'github-webhook:33333333-3333-4333-8333-333333333333',true,'2026-08-06T05:00:00Z')->>'status','pending','installation revocation registered');
select lives_ok($$select public.complete_github_webhook_installation('33333333-3333-4333-8333-333333333333',1,'revoked','2026-08-06T05:00:01Z')$$,'installation revoked');
select is((select status from public.github_installations where installation_id=81001),'revoked','trusted installation status revoked');
select is(public.register_github_webhook_delivery('44444444-4444-4444-8444-444444444444','eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee','issues','opened',81001,91001,'owner/repo','github-webhook:44444444-4444-4444-8444-444444444444',true,'2026-08-06T05:00:02Z')->>'status','ignored','revoked installation blocks later dispatch');
select ok(not exists(select 1 from information_schema.columns where table_schema='public' and table_name='github_webhook_deliveries' and column_name in ('raw_body','signature','secret','authorization','cookie','token','payload')),'no sensitive/raw columns');
select * from finish();
rollback;
